PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS store_settings(id INTEGER PRIMARY KEY CHECK(id=1), legal_name TEXT NOT NULL DEFAULT '', trade_name TEXT NOT NULL DEFAULT '', cnpj TEXT NOT NULL DEFAULT '', uf TEXT NOT NULL DEFAULT '', tax_regime TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL DEFAULT '', display_name TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'operator', active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE COLLATE NOCASE, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS suppliers(id INTEGER PRIMARY KEY, name TEXT NOT NULL COLLATE NOCASE, document TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, unit TEXT NOT NULL DEFAULT 'UN', price_cents INTEGER NOT NULL DEFAULT 0 CHECK(price_cents>=0), cost_cents INTEGER NOT NULL DEFAULT 0 CHECK(cost_cents>=0), barcode TEXT NOT NULL DEFAULT '', category_id INTEGER REFERENCES categories(id), supplier_id INTEGER REFERENCES suppliers(id), stock REAL NOT NULL DEFAULT 0 CHECK(stock>=0), ncm TEXT NOT NULL DEFAULT '', cest TEXT NOT NULL DEFAULT '', cfop TEXT NOT NULL DEFAULT '', tax_origin TEXT NOT NULL DEFAULT '', tax_profile TEXT NOT NULL DEFAULT '', track_lot INTEGER NOT NULL DEFAULT 0, track_expiry INTEGER NOT NULL DEFAULT 0, weighed_item INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, image_url TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS product_lots(id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES products(id), lot_code TEXT NOT NULL, expires_on TEXT, quantity REAL NOT NULL DEFAULT 0 CHECK(quantity>=0), UNIQUE(product_id,lot_code));
CREATE TABLE IF NOT EXISTS cash_sessions(id INTEGER PRIMARY KEY, terminal_code TEXT NOT NULL, opened_by INTEGER REFERENCES users(id), opened_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, opening_amount_cents INTEGER NOT NULL DEFAULT 0, closed_by INTEGER REFERENCES users(id), closed_at TEXT, closing_amount_cents INTEGER, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','closed')));
CREATE TABLE IF NOT EXISTS sales(id INTEGER PRIMARY KEY, sale_number TEXT NOT NULL UNIQUE, cash_session_id INTEGER REFERENCES cash_sessions(id), operator_id INTEGER REFERENCES users(id), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','completed','cancelled','refunded')), subtotal_cents INTEGER NOT NULL DEFAULT 0, discount_cents INTEGER NOT NULL DEFAULT 0, total_cents INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT);
CREATE TABLE IF NOT EXISTS sale_items(id INTEGER PRIMARY KEY, sale_id INTEGER NOT NULL REFERENCES sales(id), product_id INTEGER NOT NULL REFERENCES products(id), description TEXT NOT NULL, quantity REAL NOT NULL CHECK(quantity>0), unit_price_cents INTEGER NOT NULL CHECK(unit_price_cents>=0), discount_cents INTEGER NOT NULL DEFAULT 0, line_total_cents INTEGER NOT NULL CHECK(line_total_cents>=0));
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY, sale_id INTEGER NOT NULL REFERENCES sales(id), method TEXT NOT NULL CHECK(method IN('cash','pix','debit','credit','voucher','other')), amount_cents INTEGER NOT NULL CHECK(amount_cents>=0), external_reference TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stock_movements(id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES products(id), movement_type TEXT NOT NULL, quantity REAL NOT NULL, reference_type TEXT NOT NULL DEFAULT '', reference_id INTEGER, user_id INTEGER REFERENCES users(id), note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS equipment(id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN('scale','barcode_scanner','card_terminal')), name TEXT NOT NULL, model TEXT NOT NULL DEFAULT '', connection_type TEXT NOT NULL CHECK(connection_type IN('usb','serial','network','manual')), connection_details TEXT NOT NULL DEFAULT '', protocol TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','configured','inactive')), notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_equipment_kind ON equipment(kind,status);
CREATE TABLE IF NOT EXISTS fiscal_documents(id INTEGER PRIMARY KEY, sale_id INTEGER REFERENCES sales(id), document_model TEXT NOT NULL DEFAULT '', environment TEXT NOT NULL DEFAULT 'test', status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','authorized','rejected','cancelled','contingency','error')), access_key TEXT NOT NULL DEFAULT '', protocol TEXT NOT NULL DEFAULT '', xml_path TEXT NOT NULL DEFAULT '', response_code TEXT NOT NULL DEFAULT '', response_message TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, authorized_at TEXT);
CREATE TABLE IF NOT EXISTS license_state(id INTEGER PRIMARY KEY CHECK(id=1), license_key_id TEXT NOT NULL DEFAULT '', license_payload TEXT NOT NULL DEFAULT '', signature TEXT NOT NULL DEFAULT '', max_terminals INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'unconfigured', expires_at TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_log(id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL DEFAULT '', details TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_products_name ON products(name);
CREATE INDEX IF NOT EXISTS idx_lots_expiry ON product_lots(expires_on);
CREATE INDEX IF NOT EXISTS idx_sales_created_at ON sales(created_at);
CREATE INDEX IF NOT EXISTS idx_fiscal_status ON fiscal_documents(status);

CREATE TABLE IF NOT EXISTS customers(id INTEGER PRIMARY KEY, name TEXT NOT NULL COLLATE NOCASE, document TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS idx_customers_document ON customers(document) WHERE document<>'';
CREATE INDEX IF NOT EXISTS idx_customers_name ON customers(name);
